"use client";
import { useEffect, useState } from "react";
import { IconMoon, IconSun } from "@tabler/icons-react";
import { twMerge } from "tailwind-merge";

import { THEME_STORAGE_KEY } from "@/lib/constants";

const ThemeToggle = ({ className }: { className?: string }) => {
    const [dark, setDark] = useState(false);
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setDark(document.documentElement.classList.contains("dark"));
        setMounted(true);
    }, []);

    const toggle = () => {
        const next = !dark;
        setDark(next);
        document.documentElement.classList.toggle("dark", next);
        document.documentElement.style.colorScheme = next ? "dark" : "light";
        try {
            localStorage.setItem(THEME_STORAGE_KEY, next ? "dark" : "light");
        } catch {
            /* private mode — theme just won't persist */
        }
    };

    return (
        <button
            type="button"
            onClick={toggle}
            aria-label={dark ? "Switch to light theme" : "Switch to dark theme"}
            className={twMerge(
                "inline-flex size-10 items-center justify-center rounded-xl transition-colors hover:bg-bg-inset",
                className
            )}
        >
            {/* Before mount we don't know the theme; render the sun to keep markup stable. */}
            {mounted && dark ? <IconSun size={19} /> : <IconMoon size={19} />}
        </button>
    );
};

export default ThemeToggle;
